D = {}
D[49] = dict(title='دعا برای دفع نیرنگ دشمنان', sub='سپاس بر یاری خدا در برابر بدخواهان و حسودان',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي دِفَاعِ كَيْدِ الْأَعْدَاءِ، وَرَدِّ بَأْسِهِمْ',
 intro_fa='از دعاهای امام سجاد (ع) در دفع نیرنگ دشمنان و بازگرداندن آزارشان',
 p=[
('إِلَهِي هَدَيْتَنِي فَلَهَوْتُ، وَوَعَظْتَ فَقَسَوْتُ، وَأَبْلَيْتَ الْجَمِيلَ فَعَصَيْتُ، ثُمَّ عَرَفْتُ مَا أَصْدَرْتَ إِذْ عَرَّفْتَنِيهِ، فَاسْتَغْفَرْتُ فَأَقَلْتَ، فَعُدْتُ فَسَتَرْتَ، فَلَكَ إِلَهِي الْحَمْدُ.',
 'معبودا، مرا راه نمودی و من سرگرم [بازی] شدم، و پندم دادی و سخت‌دل شدم، و نیکی‌ات را به من نمودی و نافرمانی کردم؛ سپس چون به من شناساندی، آنچه را [از من] سر زده بود شناختم، و آمرزش خواستم و تو درگذشتی، و باز [به گناه] برگشتم و تو پوشاندی؛ پس معبودا، ستایش از آنِ توست.'),
('تَقَحَّمْتُ أَوْدِيَةَ الْهَلَاكِ، وَحَلَلْتُ شِعَابَ تَلَفٍ، تَعَرَّضْتُ فِيهَا لِسَطَوَاتِكَ، وَبِحُلُولِهَا عُقُوبَاتِكَ،',
 'خود را در دره‌های هلاکت انداختم، و در گذرگاه‌های نابودی فرود آمدم؛ گذرگاه‌هایی که در آنها خود را در معرض خشم تو، و با فرود آمدن در آنها در معرض کیفرهایت قرار دادم.'),
('وَوَسِيلَتِي إِلَيْكَ التَّوْحِيدُ، وَذَرِيعَتِي أَنِّي لَمْ أُشْرِكْ بِكَ شَيْئاً، وَلَمْ أَتَّخِذْ مَعَكَ إِلَهاً، وَقَدْ فَرَرْتُ إِلَيْكَ بِنَفْسِي، وَإِلَيْكَ مَفَرُّ الْمُسِيءِ، وَمَفْزَعُ الْمُضَيِّعِ لِحَظِّ نَفْسِهِ الْمُلْتَجِئِ.',
 'و وسیلهٔ من به سوی تو یکتاپرستی است، و دستاویزم این است که چیزی را شریک تو نساختم و همراه تو معبودی نگرفتم؛ و با همهٔ وجودم به سوی تو گریخته‌ام، و گریزگاه بدکار، و پناهگاه کسی که بهرهٔ خود را تباه کرده و پناه می‌جوید، به سوی توست.'),
('فَكَمْ مِنْ عَدُوٍّ انْتَضَى عَلَيَّ سَيْفَ عَدَاوَتِهِ، وَشَحَذَ لِي ظُبَةَ مُدْيَتِهِ، وَأَرْهَفَ لِي شَبَا حَدِّهِ، وَدَافَ لِي قَوَاتِلَ سُمُومِهِ، وَسَدَّدَ نَحْوِي صَوَائِبَ سِهَامِهِ، وَلَمْ تَنَمْ عَنِّي عَيْنُ حِرَاسَتِهِ، وَأَضْمَرَ أَنْ يَسُومَنِي الْمَكْرُوهَ، وَيُجَرِّعَنِي زُعَاقَ مَرَارَتِهِ،',
 'چه بسا دشمنی که شمشیر دشمنی‌اش را بر من کشید، و لبهٔ کاردش را برایم تیز کرد، و تیزی سلاحش را برایم برّنده ساخت، و زهرهای کشنده‌اش را برایم آمیخت، و تیرهای کارگرش را به سوی من نشانه رفت، و چشم مراقبتش از من نخوابید، و در دل داشت که مرا به ناخوشایندی گرفتار کند و آب تلخِ تلخی‌اش را جرعه‌جرعه به من بنوشاند.'),
('فَنَظَرْتَ يَا إِلَهِي إِلَى ضَعْفِي عَنِ احْتِمَالِ الْفَوَادِحِ، وَعَجْزِي عَنِ الِانْتِصَارِ مِمَّنْ قَصَدَنِي بِمُحَارَبَتِهِ، وَوَحْدَتِي فِي كَثِيرِ عَدَدِ مَنْ نَاوَانِي، وَأَرْصَدَ لِي بِالْبَلَاءِ فِيمَا لَمْ أُعْمِلْ فِيهِ فِكْرِي،',
 'پس معبودا، تو به ناتوانی‌ام از تحمل سختی‌های کمرشکن، و ناتوانی‌ام از دادخواهی از کسی که با جنگیدنش آهنگ من کرده بود، و تنهایی‌ام در برابر شمار بسیارِ کسانی که با من دشمنی کردند و با بلا در کمین من نشستند، از جایی که فکرم را در آن به کار نینداخته بودم، نگریستی.'),
('فَابْتَدَأْتَنِي بِنَصْرِكَ، وَشَدَدْتَ أَزْرِي بِقُوَّتِكَ، ثُمَّ فَلَلْتَ لِي حَدَّهُ، وَصَيَّرْتَهُ مِنْ بَعْدِ جَمْعٍ عَدِيدٍ وَحْدَهُ، وَأَعْلَيْتَ كَعْبِي عَلَيْهِ، وَجَعَلْتَ مَا سَدَّدَهُ مَرْدُوداً عَلَيْهِ،',
 'پس تو [بی‌آنکه بخواهم] با یاری‌ات آغاز کردی، و با نیرویت پشتم را محکم کردی؛ سپس تیزی‌اش را برایم کُند کردی، و او را پس از [داشتن] جمعیتی بسیار، تنها گذاشتی، و مرا بر او برتری دادی، و آنچه را نشانه گرفته بود به خودش بازگرداندی.'),
('فَرَدَدْتَهُ لَمْ يَشْفِ غَيْظَهُ، وَلَمْ يَسْكُنْ غَلِيلُهُ، قَدْ عَضَّ عَلَى شَوَاهُ، وَأَدْبَرَ مُوَلِّياً قَدْ أَخْلَفَتْ سَرَايَاهُ.',
 'پس او را بازگرداندی، در حالی که خشمش فرو ننشسته و سوز درونش آرام نگرفته بود؛ از پشیمانی انگشت به دندان گزید، و پشت کرد و رفت، در حالی که دسته‌های سپاهش ناکام مانده بودند.'),
('وَكَمْ مِنْ بَاغٍ بَغَانِي بِمَكَائِدِهِ، وَنَصَبَ لِي شَرَكَ مَصَائِدِهِ، وَوَكَّلَ بِي تَفَقُّدَ رِعَايَتِهِ، وَأَضْبَأَ إِلَيَّ إِضْبَاءَ السَّبُعِ لِطَرِيدَتِهِ، انْتِظَاراً لِانْتِهَازِ الْفُرْصَةِ لِفَرِيسَتِهِ، وَهُوَ يُظْهِرُ لِي بَشَاشَةَ الْمَلَقِ، وَيَنْظُرُنِي عَلَى شِدَّةِ الْحَنَقِ،',
 'و چه بسا ستمگری که با نیرنگ‌هایش بر من ستم کرد، و دام‌های شکارش را برایم گسترد، و مراقبت و پاییدنش را بر من گماشت، و مانند درنده‌ای که برای شکارش کمین می‌کند در کمین من نشست، به انتظار فرصت برای [گرفتن] شکارش؛ در حالی که به من روی خوشِ چاپلوسانه نشان می‌داد، و با کینه‌ای سخت به من می‌نگریست.'),
('فَلَمَّا رَأَيْتَ يَا إِلَهِي، تَبَارَكْتَ وَتَعَالَيْتَ، دَغَلَ سَرِيرَتِهِ، وَقُبْحَ مَا انْطَوَى عَلَيْهِ، أَرْكَسْتَهُ لِأُمِّ رَأْسِهِ فِي زُبْيَتِهِ، وَرَدَدْتَهُ فِي مَهْوَى حُفْرَتِهِ،',
 'پس معبودا، که خجسته و والایی، چون فریبکاری درونش و زشتی آنچه در دل داشت را دیدی، او را با سر در گودالِ [دامِ] خودش سرنگون کردی، و در ژرفای چاهی که کنده بود بازگرداندی.'),
('فَانْقَمَعَ بَعْدَ اسْتِطَالَتِهِ ذَلِيلاً فِي رِبَقِ حِبَالَتِهِ الَّتِي كَانَ يُقَدِّرُ أَنْ يَرَانِي فِيهَا، وَقَدْ كَادَ أَنْ يَحُلَّ بِي، لَوْلَا رَحْمَتُكَ، مَا حَلَّ بِسَاحَتِهِ.',
 'پس پس از گردن‌فرازی‌اش، خوار در بندهای همان دامی که گمان داشت مرا در آن ببیند، سرکوب شد؛ و اگر رحمت تو نبود، نزدیک بود آنچه بر سر او آمد بر سر من بیاید.'),
('وَكَمْ مِنْ حَاسِدٍ قَدْ شَرِقَ بِي بِغُصَّتِهِ، وَشَجِيَ مِنِّي بِغَيْظِهِ، وَسَلَقَنِي بِحَدِّ لِسَانِهِ، وَوَحَرَنِي بِقَرْفِ عُيُوبِهِ، وَجَعَلَ عِرْضِي غَرَضاً لِمَرَامِيهِ، وَقَلَّدَنِي خِلَالاً لَمْ تَزَلْ فِيهِ، وَوَحَرَنِي بِكَيْدِهِ، وَقَصَدَنِي بِمَكِيدَتِهِ،',
 'و چه بسا حسودی که از [حسد] من، غصه گلوگیرش شد، و خشمش از من در گلویش ماند، و با تیزی زبانش مرا آزرد، و با بستن عیب‌های خودش به من کینه‌اش را بر من ریخت، و آبرویم را نشانهٔ تیرهایش کرد، و خصلت‌هایی را که همیشه در خودش بود به گردن من انداخت، و با نیرنگش بر من کینه ورزید، و با حیله‌اش آهنگ من کرد.'),
('فَنَادَيْتُكَ يَا إِلَهِي مُسْتَغِيثاً بِكَ، وَاثِقاً بِسُرْعَةِ إِجَابَتِكَ، عَالِماً أَنَّهُ لَا يُضْطَهَدُ مَنْ أَوَى إِلَى ظِلِّ كَنَفِكَ، وَلَا يَفْزَعُ مَنْ لَجَأَ إِلَى مَعْقِلِ انْتِصَارِكَ، فَحَصَّنْتَنِي مِنْ بَأْسِهِ بِقُدْرَتِكَ.',
 'پس معبودا، تو را صدا زدم، در حالی که از تو فریاد می‌خواستم، و به زودی پاسخت اطمینان داشتم، و می‌دانستم کسی که به سایهٔ پناه تو درآید ستم‌دیده نمی‌ماند، و کسی که به دژ یاری تو پناه برد هراسان نمی‌شود؛ پس با قدرتت مرا از آزارش در امان داشتی.'),
('وَكَمْ مِنْ سَحَائِبِ مَكْرُوهٍ جَلَّيْتَهَا عَنِّي، وَسَحَائِبِ نِعَمٍ أَمْطَرْتَهَا عَلَيَّ، وَجَدَاوِلِ رَحْمَةٍ نَشَرْتَهَا، وَعَافِيَةٍ أَلْبَسْتَهَا، وَأَعْيُنِ أَحْدَاثٍ طَمَسْتَهَا، وَغَوَاشِي كُرُبَاتٍ كَشَفْتَهَا،',
 'و چه بسا ابرهای ناخوشایندی که از من کنار زدی، و ابرهای نعمتی که بر من باراندی، و جوی‌های رحمتی که روان کردی، و عافیتی که بر من پوشاندی، و چشمِ پیشامدهای بدی که کور کردی، و پرده‌های اندوهی که کنار زدی.'),
('وَكَمْ مِنْ ظَنٍّ حَسَنٍ حَقَّقْتَ، وَعَدَمٍ جَبَرْتَ، وَصَرْعَةٍ أَنْعَشْتَ، وَمَسْكَنَةٍ حَوَّلْتَ،',
 'و چه بسا گمان نیکی که تحقق بخشیدی، و تنگدستی‌ای که جبران کردی، و زمین‌خوردگی‌ای که [مرا از آن] برخیزاندی، و بیچارگی‌ای که دگرگون کردی.'),
('كُلُّ ذَلِكَ إِنْعَاماً وَتَطَوُّلاً مِنْكَ، وَفِي جَمِيعِهِ انْهِمَاكاً مِنِّي عَلَى مَعَاصِيكَ، لَمْ تَمْنَعْكَ إِسَاءَتِي عَنْ إِتْمَامِ إِحْسَانِكَ، وَلَا حَجَزَنِي ذَلِكَ عَنِ ارْتِكَابِ مَسَاخِطِكَ،',
 'همهٔ اینها از سرِ نعمت‌بخشی و بزرگواری تو بود، و در همهٔ آن، من غرق در نافرمانی‌ات بودم؛ نه بدی من تو را از کامل کردن نیکی‌ات بازداشت، و نه این [نیکی تو] مرا از انجام آنچه تو را خشمگین می‌کند بازداشت.'),
('لَا تُسْأَلُ عَمَّا تَفْعَلُ، وَلَقَدْ سُئِلْتَ فَأَعْطَيْتَ، وَلَمْ تُسْأَلْ فَابْتَدَأْتَ، وَاسْتُمِيحَ فَضْلُكَ فَمَا أَكْدَيْتَ،',
 'از آنچه می‌کنی بازخواست نمی‌شوی؛ و به راستی از تو خواسته شد و عطا کردی، و خواسته نشد و خود آغاز کردی، و بخشش تو طلب شد و دریغ نکردی.'),
('أَبَيْتَ يَا مَوْلَايَ إِلَّا إِحْسَاناً وَامْتِنَاناً وَتَطَوُّلاً وَإِنْعَاماً، وَأَبَيْتُ إِلَّا تَقَحُّماً لِحُرُمَاتِكَ، وَتَعَدِّياً لِحُدُودِكَ، وَغَفْلَةً عَنْ وَعِيدِكَ،',
 'ای مولای من، تو جز نیکی و منت و بزرگواری و نعمت‌بخشی نخواستی، و من جز درافتادن به حریم‌هایت، و تجاوز از مرزهایت، و غفلت از هشدارهایت نخواستم.'),
('فَلَكَ الْحَمْدُ إِلَهِي مِنْ مُقْتَدِرٍ لَا يُغْلَبُ، وَذِي أَنَاةٍ لَا يَعْجَلُ، هَذَا مَقَامُ مَنِ اعْتَرَفَ بِسُبُوغِ النِّعَمِ، وَقَابَلَهَا بِالتَّقْصِيرِ، وَشَهِدَ عَلَى نَفْسِهِ بِالتَّضْيِيعِ.',
 'پس معبودا، ستایش از آنِ توست؛ توانایی که شکست نمی‌خورد، و بردباری که شتاب نمی‌کند. این جایگاه کسی است که به فراوانی نعمت‌ها اعتراف کرده، و با کوتاهی با آنها روبه‌رو شده، و بر ضد خود به تباه کردن [آنها] گواهی داده است.'),
('اللّٰهُمَّ فَإِنِّي أَتَقَرَّبُ إِلَيْكَ بِالْمُحَمَّدِيَّةِ الرَّفِيعَةِ، وَالْعَلَوِيَّةِ الْبَيْضَاءِ، وَأَتَوَجَّهُ إِلَيْكَ بِهِمَا أَنْ تُعِيذَنِي مِنْ شَرِّ كَذَا وَكَذَا،',
 'خدایا، پس من با [مقام] بلندِ محمدی و [مقام] روشنِ علوی به تو نزدیکی می‌جویم، و با آن دو به تو روی می‌آورم که مرا از شرّ فلان و فلان پناه دهی [در اینجا خواستهٔ خود را نام ببرید].'),
('فَإِنَّ ذَلِكَ لَا يَضِيقُ عَلَيْكَ فِي وُجْدِكَ، وَلَا يَتَكَأَّدُكَ فِي قُدْرَتِكَ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ،',
 'زیرا این کار با توانگری‌ات بر تو تنگ نمی‌آید، و با قدرتت برایت دشوار نیست، و تو بر هر چیز توانایی.'),
('فَهَبْ لِي يَا إِلَهِي مِنْ رَحْمَتِكَ وَدَوَامِ تَوْفِيقِكَ مَا أَتَّخِذُهُ سُلَّماً أَعْرُجُ بِهِ إِلَى رِضْوَانِكَ، وَآمَنُ بِهِ مِنْ عِقَابِكَ، يَا أَرْحَمَ الرَّاحِمِينَ.',
 'پس معبودا، از رحمتت و توفیق همیشگی‌ات چیزی به من ببخش که آن را نردبانی کنم که با آن به خشنودی‌ات بالا روم، و با آن از کیفرت ایمن شوم؛ ای مهربان‌ترین مهربانان.'),
])
